import http.server as h
class H(h.SimpleHTTPRequestHandler):
    extensions_map = {**h.SimpleHTTPRequestHandler.extensions_map, '.js': 'text/javascript'}
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store')
        super().end_headers()
h.test(HandlerClass=H, port=8011, bind='127.0.0.1')
